  // 方法三：在初始化的时候，可以省去数据类型，通过值自动匹配当前的变量的数据类型
  var c = 100
  fmt.Println("c =", c)
  fmt.Printf("type of c = %T\n", c)

  var c1 = "hello go"
  fmt.Printf("c1 = '%s', type of c1 = %T\n", c1, c1)

  // 方法四：常用 省去var关键字，直接自动匹配
  e := 100
  fmt.Println("e =", e)
  fmt.Printf("type of e = %T\n", e)


  // 全局变量打印
  fmt.Println(num1, num2)
}

