	h.Walk()

	s := SuperMan{Human{"李4", "男"}, 18}

	s.Eat()
  s.Walk() // 因为Walk()方法，没有重写，所以调用的是父类的Walk()方法
	s.Fly()
}
/*
Human.Eat()... &{张三 女}
Human.Walk()...
SuperMan.Eat()... &{{李4 男} 18}
Human.Walk()...
SuperMan.Fly()...
*/

