package com.ganto.www;
// 顾客类
public class Customer {
		// 定义了一个私有的FoodMenu类型的引用
    private FoodMenu menu;

  	// 无参构造方法
    public Customer() { }
		// 有参构造方法
    public Customer(FoodMenu menu) {
        this.menu = menu;
    }

  	// getter setter方法
    public FoodMenu getMenu() {
        return menu;
