```java
package org.example;

import java.util.Random;

public class Main {
    public static void main(String[] args) throws Exception {
        int[] arr = new int[5];

        Random random = new Random();
        int num;

        int count = 0;


        while (count < 5) {
            num = random.nextInt(5);
            int count1 = 0;
            if(count == 0) {
                arr[count] = num;
                count++;
            }
            for (int i = 0; i < count; i++) {
