# 泛型机制

JDK5.0之后推出的新特性：泛型

## 不使用泛型

不使用泛型机制，分析程序存在的缺点

```java
package com.ganto;

import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

/**
 * JDK5.0之后推出的新特性：泛型
 */
public class Main {
    public static void main(String[] args) {
        // 不使用泛型机制，分析程序存在的缺点

        // 创建一个集合
        List myList = new ArrayList();
        // 准备对象
        Cat c = new Cat();
        Bird b = new Bird();
        // 将对象添加到集合当中
        myList.add(c);
        myList.add(b);
        // 遍历集合，取出Cat让它抓老鼠，取出Brid让它飞
        Iterator it = myList.iterator();
        while (it.hasNext()) {
            // 通过迭代器去除的obj就是Object类型，不用泛型的话下面必须强转
            Object obj = it.next();
            if(obj instanceof Animal) {
                ((Animal) obj).move();
            }
        }
    }
}
class Animal {
    public void move() {
        System.out.println("动物在移动！");
    }
}
class Cat extends Animal {
    public void catchMouse() {
        System.out.println("猫抓老鼠！");
    }
}
class Bird extends Animal {
    public void fly() {
        System.out.println("鸟儿在飞翔！");
    }
}

```

## 使用泛型

```java
package com.ganto;

import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

/**
 * JDK5.0之后推出的新特性：泛型
 */
public class Main {
    public static void main(String[] args) {
        // 使用泛型机制

        // 使用泛型之后,表示List集合中只允许存储Animal类型的数据
        // 用泛型来指定集合中存储的数据类型
        List<Animal> myList = new ArrayList<Animal>();

        // 指定了List集合中只能存储Animal,那么存储String就会编译报错
        // 这样用了泛型之后,集合中元素的数据类型更加统一
        // myList.add("123"); // 报错 需要的类型: Animal 提供的类型: String

        Cat c = new Cat();
        Bird b = new Bird();
        myList.add(c);
        myList.add(b);

        // 获取迭代器
      	// 这个表示迭代器迭代的是Animal类型
        Iterator<Animal> it = myList.iterator();
        while (it.hasNext()) {
          	// 使用泛型之后，每次迭代返回的数据都是Animal类型
            Animal a = it.next();
          	// 这里就不需要进行强制类型转换了
            a.move();
          	// 调用子类特有的方法还是避免不了要向下转型
          	if(a instanceof Cat) {
              	((Cat) a).catchMouse();
            } else if(a instanceof Bird) {
              	((Bird) a).fly();
            }
        }
    }
}
class Animal {
    public void move() {
        System.out.println("动物在移动！");
    }
}
class Cat extends Animal {
    public void catchMouse() {
        System.out.println("猫抓老鼠！");
    }
}
